1	// Package store owns the SQLite file and every write the service performs.
2	package store
3	
4	import (
5		"database/sql"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"strings"
10		"sync"
11	
12		_ "modernc.org/sqlite"
13	)
14	
15	// ErrConflict reports that a net policy identity already holds different content.
16	var ErrConflict = errors.New("net policy identity holds different content")
17	
18	// Rule is one allow/deny statement bound to a closed port interval.
19	type Rule struct {
20		Direction string `json:"direction"`
21		Action    string `json:"action"`
22		Ports     [2]int `json:"ports"`
23	}
24	
25	// Record is a committed net policy together with its registry metadata.
26	type Record struct {
27		Namespace    string            `json:"namespace"`
28		Name         string            `json:"name"`
29		Label        string            `json:"label"`
30		Rules        []Rule            `json:"rules"`
31		PluginParams map[string]string `json:"pluginParams"`
32		Order        int64             `json:"order"`
33		Conflict     bool              `json:"conflict"`
34	}
35	
36	// Store wraps the SQLite handle so callers never touch database/sql directly.
37	type Store struct {
38		db *sql.DB
39		mu sync.Mutex
40	}
41	
42	// Open prepares the database file and the schema this service needs.
43	func Open(path string) (*Store, error) {
44		db, err := sql.Open("sqlite", path)
45		if err != nil {
46			return nil, fmt.Errorf("open sqlite: %w", err)
47		}
48		if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
49			db.Close()
50			return nil, fmt.Errorf("enable wal: %w", err)
51		}
52		if _, err := db.Exec(schema); err != nil {
53			db.Close()
54			return nil, fmt.Errorf("apply schema: %w", err)
55		}
56		return &Store{db: db}, nil
57	}
58	
59	// Ping reports whether the storage layer is usable.
60	func (s *Store) Ping() error { return s.db.Ping() }
61	
62	// Close releases the database handle.
63	func (s *Store) Close() error { return s.db.Close() }
64	
65	// Register commits a new net policy. Retrying an identity with identical content
66	// returns the stored record with created=false; different content yields ErrConflict.
67	// The whole check-and-insert runs under one lock and one transaction so a failed
68	// registration leaves nothing behind and concurrent submits keep a single row.
69	func (s *Store) Register(rec Record) (stored Record, created bool, err error) {
70		rulesJSON, err := json.Marshal(rec.Rules)
71		if err != nil {
72			return Record{}, false, fmt.Errorf("encode rules: %w", err)
73		}
74		paramsJSON, err := json.Marshal(rec.PluginParams)
75		if err != nil {
76			return Record{}, false, fmt.Errorf("encode plugin params: %w", err)
77		}
78		content := contentKey(rec.Label, rulesJSON, paramsJSON)
79	
80		s.mu.Lock()
81		defer s.mu.Unlock()
82	
83		tx, err := s.db.Begin()
84		if err != nil {
85			return Record{}, false, fmt.Errorf("begin register: %w", err)
86		}
87		defer tx.Rollback()
88	
89		var (
90			existing                                       Record
91			existingRules, existingParams, existingContent string
92			existingConflict                               int
93		)
94		row := tx.QueryRow(
95			`SELECT label, rules, plugin_params, content, seq, conflict
96			 FROM net_policies WHERE namespace = ? AND name = ?`,
97			rec.Namespace, rec.Name)
98		scanErr := row.Scan(&existing.Label, &existingRules, &existingParams, &existingContent, &existing.Order, &existingConflict)
99		switch {
100		case scanErr == nil:
101			if existingContent != content {
102				return Record{}, false, ErrConflict
103			}
104			existing.Namespace, existing.Name = rec.Namespace, rec.Name
105			existing.Conflict = existingConflict != 0
106			if err := json.Unmarshal([]byte(existingRules), &existing.Rules); err != nil {
107				return Record{}, false, fmt.Errorf("decode stored rules: %w", err)
108			}
109			if err := json.Unmarshal([]byte(existingParams), &existing.PluginParams); err != nil {
110				return Record{}, false, fmt.Errorf("decode stored plugin params: %w", err)
111			}
112			return existing, false, nil
113		case !errors.Is(scanErr, sql.ErrNoRows):
114			return Record{}, false, fmt.Errorf("lookup net policy: %w", scanErr)
115		}
116	
117		conflict, err := detectConflict(tx, rec)
118		if err != nil {
119			return Record{}, false, err
120		}
121	
122		var next int64
123		if err := tx.QueryRow(`SELECT COALESCE(MAX(seq), 0) + 1 FROM net_policies`).Scan(&next); err != nil {
124			return Record{}, false, fmt.Errorf("assign order: %w", err)
125		}
126		conflictFlag := 0
127		if conflict {
128			conflictFlag = 1
129		}
130		if _, err := tx.Exec(
131			`INSERT INTO net_policies (namespace, name, label, rules, plugin_params, content, seq, conflict)
132			 VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
133			rec.Namespace, rec.Name, rec.Label, string(rulesJSON), string(paramsJSON), content, next, conflictFlag); err != nil {
134			return Record{}, false, fmt.Errorf("insert net policy: %w", err)
135		}
136		if err := tx.Commit(); err != nil {
137			return Record{}, false, fmt.Errorf("commit net policy: %w", err)
138		}
139		rec.Order = next
140		rec.Conflict = conflict
141		return rec, true, nil
142	}
143	
144	// List returns committed records filtered by the non-empty conditions, ordered by seq.
145	func (s *Store) List(namespace, label string) ([]Record, error) {
146		query := `SELECT namespace, name, label, rules, plugin_params, seq, conflict FROM net_policies`
147		var conds []string
148		var args []any
149		if namespace != "" {
150			conds = append(conds, "namespace = ?")
151			args = append(args, namespace)
152		}
153		if label != "" {
154			conds = append(conds, "label = ?")
155			args = append(args, label)
156		}
157		if len(conds) > 0 {
158			query += " WHERE " + strings.Join(conds, " AND ")
159		}
160		query += " ORDER BY seq ASC"
161	
162		rows, err := s.db.Query(query, args...)
163		if err != nil {
164			return nil, fmt.Errorf("list net policies: %w", err)
165		}
166		defer rows.Close()
167	
168		var records []Record
169		for rows.Next() {
170			var (
171				rec                 Record
172				rulesRaw, paramsRaw string
173				conflictFlag        int
174			)
175			if err := rows.Scan(&rec.Namespace, &rec.Name, &rec.Label, &rulesRaw, &paramsRaw, &rec.Order, &conflictFlag); err != nil {
176				return nil, fmt.Errorf("scan net policy: %w", err)
177			}
178			if err := json.Unmarshal([]byte(rulesRaw), &rec.Rules); err != nil {
179				return nil, fmt.Errorf("decode stored rules: %w", err)
180			}
181			if err := json.Unmarshal([]byte(paramsRaw), &rec.PluginParams); err != nil {
182				return nil, fmt.Errorf("decode stored plugin params: %w", err)
183			}
184			rec.Conflict = conflictFlag != 0
185			records = append(records, rec)
186		}
187		if err := rows.Err(); err != nil {
188			return nil, fmt.Errorf("iterate net policies: %w", err)
189		}
190		return records, nil
191	}
192	
193	// detectConflict reports whether the candidate record clashes with any committed
194	// record sharing its namespace and label: same direction, opposite action, and
195	// overlapping port intervals.
